<?php
declare(strict_types=1);
namespace App\Application\QuestionBank\Service;
use App\Application\QuestionBank\DTO\Request\AssignQuestionTaxonomySubjectsRequestDto;use App\Application\Study\Port\TransactionManagerInterface;use App\Domain\QuestionBank\Repository\EditorialQuestionRepositoryInterface;use App\Domain\QuestionBank\Repository\QuestionTaxonomyAssignmentRepositoryInterface;use App\Domain\Taxonomy\Repository\TaxonomySubjectRepositoryInterface;
final class AssignQuestionTaxonomySubjectsService { public function __construct(private readonly EditorialQuestionRepositoryInterface $questions,private readonly TaxonomySubjectRepositoryInterface $subjects,private readonly QuestionTaxonomyAssignmentRepositoryInterface $assignments,private readonly TransactionManagerInterface $transactions){} public function assign(AssignQuestionTaxonomySubjectsRequestDto $input):void{$this->transactions->transactional(function()use($input){if(!$this->questions->exists($input->questionId))throw new \DomainException('Questao nao encontrada.');$ids=array_values(array_unique($input->taxonomySubjectIds));foreach($ids as $id){if($this->subjects->findById($id)===null)throw new \DomainException('Assunto canonico nao encontrado.');}$this->assignments->replaceForQuestion($input->questionId,$ids);});} }
